contracts/CathedralCredit.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./CathedralSBT.sol";

contract CathedralCredit is AccessControl {
    CathedralSBT public sbtContract;
    IERC20 public lusdToken;

    struct Loan {
        address borrower;
        uint256 amount;
        uint256 startTime;
        uint256 endTime;
        bool repaid;
        bool defaulted;
    }

    mapping(uint256 => Loan) public loans;
    uint256 public loanCounter;
    mapping(address => uint256) public outstandingLoans;
    uint256 public treasuryBalance;
    uint256 public treasuryCapPercent = 80;
    uint256 public minSRSForLoan = 60;
    uint256 public baseCreditLimit = 100 * 1e18;

    event LoanRequested(uint256 indexed loanId, address indexed borrower, uint256 amount, uint256 duration);
    event LoanRepaid(uint256 indexed loanId, address indexed borrower);
    event LoanDefaulted(uint256 indexed loanId, address indexed borrower);

    constructor(address _sbtContract, address _lusdToken) {
        require(_sbtContract != address(0), "CathedralCredit: Invalid SBT contract");
        require(_lusdToken != address(0), "CathedralCredit: Invalid LUSD token");

        sbtContract = CathedralSBT(_sbtContract);
        lusdToken = IERC20(_lusdToken);
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    function creditLimit(address wallet) public view returns (uint256) {
        if (sbtContract.balanceOf(wallet) == 0) return 0;
        if (sbtContract.getCurrentSRS(wallet) < minSRSForLoan) return 0;

        uint256 repaymentCount = sbtContract.getRepaymentHistory(wallet);
        uint256 limit = baseCreditLimit + (repaymentCount * 10 * 1e18);

        return limit;
    }

    function requestLoan(uint256 amount, uint256 duration) external {
        require(amount > 0, "CathedralCredit: Amount must be > 0");
        require(duration >= 7 days && duration <= 180 days, "CathedralCredit: Invalid duration");
        require(sbtContract.balanceOf(msg.sender) > 0, "CathedralCredit: No SBT");
        require(sbtContract.getCurrentSRS(msg.sender) >= minSRSForLoan, "CathedralCredit: SRS too low");
        require(amount <= creditLimit(msg.sender), "CathedralCredit: Exceeds credit limit");

        uint256 totalOutstanding = getTotalOutstandingLoans();
        uint256 treasuryCap = (treasuryBalance * treasuryCapPercent) / 100;
        require(totalOutstanding + amount <= treasuryCap, "CathedralCredit: Treasury cap reached");
        require(lusdToken.balanceOf(address(this)) >= amount, "CathedralCredit: Insufficient treasury");

        uint256 loanId = loanCounter++;
        loans[loanId] = Loan({
            borrower: msg.sender,
            amount: amount,
            startTime: block.timestamp,
            endTime: block.timestamp + duration,
            repaid: false,
            defaulted: false
        });

        outstandingLoans[msg.sender] += amount;
        require(lusdToken.transfer(msg.sender, amount), "CathedralCredit: LUSD transfer failed");

        emit LoanRequested(loanId, msg.sender, amount, duration);
    }

    function repayLoan(uint256 loanId) external {
        Loan storage loan = loans[loanId];
        require(loan.borrower == msg.sender, "CathedralCredit: Not your loan");
        require(!loan.repaid, "CathedralCredit: Loan already repaid");
        require(!loan.defaulted, "CathedralCredit: Loan already defaulted");
        require(block.timestamp <= loan.endTime, "CathedralCredit: Loan overdue");

        require(lusdToken.transferFrom(msg.sender, address(this), loan.amount), "CathedralCredit: Repayment failed");

        loan.repaid = true;
        outstandingLoans[msg.sender] -= loan.amount;
        sbtContract.recordRepayment(msg.sender, loanId);

        uint256 newSRS = sbtContract.getCurrentSRS(msg.sender) + 5;
        if (newSRS > 100) newSRS = 100;
        sbtContract.updateScore(msg.sender, newSRS, "repayment");

        emit LoanRepaid(loanId, msg.sender);
    }

    function getTotalOutstandingLoans() public view returns (uint256) {
        uint256 total = 0;
        for (uint256 i = 0; i < loanCounter; i++) {
            if (!loans[i].repaid && !loans[i].defaulted) {
                total += loans[i].amount;
            }
        }
        return total;
    }

    function depositTreasury(uint256 amount) external {
        require(lusdToken.transferFrom(msg.sender, address(this), amount), "CathedralCredit: Deposit failed");
        treasuryBalance += amount;
    }

    function withdrawTreasury(uint256 amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(treasuryBalance >= amount, "CathedralCredit: Insufficient treasury");
        require(lusdToken.transfer(msg.sender, amount), "CathedralCredit: Withdrawal failed");
        treasuryBalance -= amount;
    }
}

contracts/CathedralOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "./CathedralSBT.sol";

contract CathedralOracle is AccessControl {
    bytes32 public constant SIGNER_ROLE = keccak256("SIGNER_ROLE");

    CathedralSBT public sbtContract;
    mapping(bytes32 => bool) public usedSignatures;
    address public backendSigner;

    event SBTMintedViaOracle(address indexed wallet, uint256 srsScore);

    constructor(address _sbtContract, address _backendSigner) {
        sbtContract = CathedralSBT(_sbtContract);
        backendSigner = _backendSigner;
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(SIGNER_ROLE, _backendSigner);
    }

    function mintSBT(
        address wallet,
        uint256 srsScore,
        bytes32 behaviorFingerprint,
        uint256 timestamp,
        bytes memory signature
    ) external {
        require(block.timestamp <= timestamp + 5 minutes, "Signature expired");

        bytes32 messageHash = keccak256(abi.encodePacked(wallet, srsScore, behaviorFingerprint, timestamp));
        require(!usedSignatures[messageHash], "Signature already used");

        // Manual Ethereum signed message prefix (compatible with older ethers)
        bytes32 prefixedHash = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash));
        address signer = ECDSA.recover(prefixedHash, signature);
        require(signer == backendSigner, "Invalid signature");

        usedSignatures[messageHash] = true;
        sbtContract.mintSBT(wallet, srsScore, behaviorFingerprint);

        emit SBTMintedViaOracle(wallet, srsScore);
    }
}

contracts/CathedralSBT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

contract CathedralSBT is ERC721, AccessControl {
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");
    bytes32 public constant CREDIT_CONTRACT_ROLE = keccak256("CREDIT_CONTRACT_ROLE");

    struct SBTData {
        uint256 srsScore;
        uint256 lastScoringTimestamp;
        uint256 successfulRepayments;
        uint256 defaultCount;
        bool blacklisted;
        bytes32 behaviorFingerprint;
    }

    mapping(address => SBTData) public sbtData;

    event SBTMinted(address indexed wallet, uint256 srsScore, uint256 timestamp);
    event ScoreUpdated(address indexed wallet, uint256 oldScore, uint256 newScore, string reason);
    event RepaymentMade(address indexed wallet, uint256 loanId, uint256 newRepaymentCount);

    constructor() ERC721("Cathedral Soulbound Token", "CATH-SBT") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ORACLE_ROLE, msg.sender);
    }

    function mintSBT(address to, uint256 srsScore, bytes32 behaviorFingerprint) 
        external 
        onlyRole(ORACLE_ROLE) 
    {
        require(balanceOf(to) == 0, "CathedralSBT: Already has SBT");
        require(srsScore >= 50, "CathedralSBT: SRS too low for minting");

        uint256 tokenId = uint256(uint160(to));
        _safeMint(to, tokenId);

        sbtData[to] = SBTData({
            srsScore: srsScore,
            lastScoringTimestamp: block.timestamp,
            successfulRepayments: 0,
            defaultCount: 0,
            blacklisted: false,
            behaviorFingerprint: behaviorFingerprint
        });

        emit SBTMinted(to, srsScore, block.timestamp);
    }

    function updateScore(address wallet, uint256 newScore, string calldata reason) 
        external 
    {
        require(hasRole(ORACLE_ROLE, msg.sender) || hasRole(CREDIT_CONTRACT_ROLE, msg.sender), 
                "CathedralSBT: Unauthorized");
        require(balanceOf(wallet) > 0, "CathedralSBT: No SBT for wallet");

        uint256 oldScore = sbtData[wallet].srsScore;
        sbtData[wallet].srsScore = newScore;
        sbtData[wallet].lastScoringTimestamp = block.timestamp;

        emit ScoreUpdated(wallet, oldScore, newScore, reason);
    }

    function recordRepayment(address wallet, uint256 loanId) external onlyRole(CREDIT_CONTRACT_ROLE) {
        sbtData[wallet].successfulRepayments++;
        emit RepaymentMade(wallet, loanId, sbtData[wallet].successfulRepayments);
    }

    function getCurrentSRS(address wallet) external view returns (uint256) {
        require(balanceOf(wallet) > 0, "CathedralSBT: No SBT for wallet");
        return sbtData[wallet].srsScore;
    }

    function getRepaymentHistory(address wallet) external view returns (uint256) {
        return sbtData[wallet].successfulRepayments;
    }

    function getDefaultCount(address wallet) external view returns (uint256) {
        return sbtData[wallet].defaultCount;
    }

